sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float hue;
half4 main(float2 coord) {
    half4 c = unpremul(image.eval(coord));
    float a = radians(-hue);
    float3 v = float3(c.rgb);
    float y = dot(v, float3(0.299, 0.587, 0.114));
    float2 uv = float2(dot(v, float3(-0.14713, -0.28886, 0.436)), dot(v, float3(0.615, -0.51499, -0.10001)));
    uv = float2(uv.x * cos(a) - uv.y * sin(a), uv.x * sin(a) + uv.y * cos(a));
    v = float3(y + 1.13983 * uv.y, y - 0.39465 * uv.x - 0.5806 * uv.y, y + 2.03211 * uv.x);
    return half4(half3(saturate(v)) * c.a, c.a);
}
